// N18 C2 fix round 2: what tone() costs in the sketch the generator writes (buzzerTone(BUZZER_PIN, <hz>, <ms>), contract U-25), by
// Timer2 prescaler band, with the frequency a literal (constant: -flto folds the prescaler search) and computed at run time (from
// two analogRead), on a pin that plays nothing and on the one that plays. The evidence of contract 0.1.6's toneUs (EMU-18).
//
// Method: each program is made of blocks and generated by the real generator (tests/parity/fixtures.ts, through Vite SSR as
// scripts/build-parity-hex.mjs loads it), compiled with the pinned arduino-cli and run on avr8js (tests/parity/emulated-uno.ts).
// Each sample is `LED on; buzzerTone(…); LED off` with nothing else between: the LED's ON→OFF time minus that of `LED on; LED off`
// in the same program is the buzzerTone statement. Three samples per frequency, the shortest kept (an interrupt can land in one);
// the tone that plays before a "playing" sample is 31 Hz, so its own interrupt (every 16 ms) does not land in the sample.
//
// - `bands`: 25 frequencies, the edges and the inside of each band, in four programs (constant or computed frequency, silent or
//   playing pin) of 75 calls each. With that many call sites -flto keeps one buzzerTone and one tone(): the unfolded cost.
// - `fold`: the same statement at 1000 Hz (and others) in programs of 1, 2, 3 and 5 call sites, constant and computed: with few
//   call sites -flto inlines buzzerTone and tone() and folds a constant frequency, so the cost depends on the whole program.
// - `oneSite`: one literal call site at a frequency of every band: what is left of tone() once folded.
//
//   node spikes/avr8js/run-generated-tone.mjs        # ≈ 20 s; prints JSON
import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../..');
const { createServer } = await import(join(root, 'node_modules/vite/dist/node/index.js'));

/** By band (Tone.cpp chooses prescaler p once floor(8e6 / (p · f)) ≤ 256): its edges and inside it. */
export const FREQUENCIES = [31, 60, 100, 121, 122, 150, 200, 243, 244, 300, 440, 486, 487, 600, 800, 972, 973, 1000, 1500, 2000, 3000, 3891, 3892, 3950, 4000];
const REPEATS = 3;
const TONE_MS = 20;

const server = await createServer({
  root,
  configFile: false,
  logLevel: 'error',
  appType: 'custom',
  server: { middlewareMode: true, hmr: false, ws: false },
  optimizeDeps: { noDiscovery: true, include: [] },
});
try {
  const { sketchOf } = await server.ssrLoadModule('/tests/parity/fixtures.ts');
  const { buzzerStop, buzzerTone, led, lineRaw } = await server.ssrLoadModule('/src/core/program/__fixtures__/uno-blocks.ts');
  const { add, getVar, mul, num, setVar, wait } = await server.ssrLoadModule('/src/core/program/__fixtures__/ybc-blocks.ts');
  const { EmulatedUno, cyclesOfUs, usOfCycles } = await server.ssrLoadModule('/tests/parity/emulated-uno.ts');
  const { parseIntelHex } = await server.ssrLoadModule('/tests/parity/intel-hex.ts');

  const computedHz = () => add(mul(lineRaw('lineLeft'), num(1000)), lineRaw('lineCenter'));
  const forms = {
    'constant-silent': (hz) => [led('ON'), buzzerTone(num(hz), num(TONE_MS)), led('OFF'), wait(num(TONE_MS + 5))],
    'constant-playing': (hz) => [buzzerTone(num(31), num(200)), wait(num(2)), led('ON'), buzzerTone(num(hz), num(TONE_MS)), led('OFF'), wait(num(TONE_MS + 5))],
    'computed-silent': () => [setVar('x', computedHz()), led('ON'), buzzerTone(getVar('x'), num(TONE_MS)), led('OFF'), wait(num(TONE_MS + 5))],
    'computed-playing': () => [setVar('x', computedHz()), buzzerTone(num(31), num(200)), wait(num(2)), led('ON'), buzzerTone(getVar('x'), num(TONE_MS)), led('OFF'), wait(num(TONE_MS + 5))],
  };
  const baseline = () => [led('ON'), led('OFF'), wait(num(1))];

  /** Generates, compiles and runs one program; the LED pulses (ON→OFF, µs) after setup(), the computed frequencies fed in order. */
  const pulsesOf = (name, onStart, frequencies) => {
    const source = sketchOf({ name, covers: [], profile: 'uno-advanced', onStart, variables: [['x', 'x']], origin: 'language', durationMs: 0, inputs: {} });
    const sketchDir = join(here, 'build', 'sketches', name);
    const buildDir = join(here, 'build', name);
    mkdirSync(sketchDir, { recursive: true });
    writeFileSync(join(sketchDir, `${name}.ino`), source);
    const compiled = spawnSync('arduino-cli', ['compile', '--fqbn', 'arduino:avr:uno', '--build-path', buildDir, sketchDir], { encoding: 'utf8' });
    if (compiled.status !== 0) {
      throw new Error(`${name} does not compile:\n${compiled.stdout}\n${compiled.stderr}`);
    }
    const uno = new EmulatedUno(parseIntelHex(readFileSync(join(buildDir, `${name}.ino.hex`), 'utf8')));
    // The computed frequency: lineLeft · 1000 + lineCenter, read in that order.
    const adc = frequencies.flatMap((hz) => [Math.floor(hz / 1000), hz % 1000]);
    uno.analogValue = () => adc.shift() ?? 0;
    uno.drive('D3', true);
    uno.runUntil(cyclesOfUs((frequencies.length * (TONE_MS + 10) + 10) * 1000 * 1.1));
    const led13 = uno.changes.filter((change) => change.pin === 'D13' && change.cycle > (uno.setupCycle ?? 0) && (change.state === 'HIGH' || change.state === 'LOW'));
    const pulses = [];
    for (let index = 0; index + 1 < led13.length; index++) {
      if (led13[index].state === 'HIGH' && led13[index + 1].state === 'LOW') {
        pulses.push(usOfCycles(led13[index + 1].cycle - led13[index].cycle));
      }
    }
    return pulses;
  };

  const bands = {};
  for (const [form, sample] of Object.entries(forms)) {
    const onStart = [...Array.from({ length: REPEATS }, baseline).flat(), ...FREQUENCIES.flatMap((hz) => Array.from({ length: REPEATS }, () => sample(hz)).flat()), buzzerStop()];
    const pulses = pulsesOf(`generated-tone-${form}`, onStart, FREQUENCIES.flatMap((hz) => Array.from({ length: REPEATS }, () => hz)));
    const base = Math.min(...pulses.slice(0, REPEATS));
    const costs = {};
    FREQUENCIES.forEach((hz, k) => {
      const samples = pulses.slice(REPEATS + k * REPEATS, REPEATS + (k + 1) * REPEATS);
      costs[hz] = { us: Math.min(...samples) - base, samples: samples.map((us) => us - base) };
    });
    bands[form] = { ledOnOffUs: base, costs };
  }

  const FOLD_FREQUENCIES = [1000, 440, 4000, 31, 1500];
  const fold = {};
  for (const sites of [1, 2, 3, 5]) {
    for (const [form, sample] of Object.entries({ constant: forms['constant-silent'], computed: forms['computed-silent'] })) {
      const frequencies = FOLD_FREQUENCIES.slice(0, sites);
      const onStart = [...baseline(), ...frequencies.flatMap((hz) => sample(hz))];
      const pulses = pulsesOf(`generated-tone-fold-${form}-${sites}`, onStart, frequencies);
      fold[`${form}, ${sites} call sites`] = Object.fromEntries(frequencies.map((hz, k) => [hz, (pulses[k + 1] ?? NaN) - (pulses[0] ?? NaN)]));
    }
  }
  // One literal call site at a frequency of every band: what the fold leaves of tone() whatever the band.
  const oneSite = {};
  for (const hz of [31, 60, 121, 122, 200, 244, 440, 487, 1000, 4000]) {
    const pulses = pulsesOf(`generated-tone-fold-literal-${hz}`, [...baseline(), ...forms['constant-silent'](hz)], [hz]);
    oneSite[hz] = (pulses[1] ?? NaN) - (pulses[0] ?? NaN);
  }
  console.log(JSON.stringify({ bands, fold, oneSite }, null, 2));
} finally {
  await server.close();
}
